import ctypes
from numpy import array, asarray

def qr_decomposition(U, D, Y, T):
    libgslcblas = ctypes.CDLL('/usr/local/gsl/lib/libgslcblas.so', mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL('/usr/local/gsl/lib/libgsl.so')

    def numpy_to_gsl_matrix(matrix):
        return gsl.gsl_matrix_alloc(matrix.shape[0], matrix.shape[1])

def numpy_to_gsl_vector(vector):
        return gsl.gsl_vector_alloc(vector.size)

    U = numpy_to_gsl_matrix(U)
    D = numpy_to_gsl_matrix(D)
    Y = numpy_to_gsl_matrix(Y)
    T = numpy_to_gsl_vector(T)

    qr_ud_decomp = gsl.qr_ud_decomp
    qr_ud_decomp.argtypes = [ctypes.POINTER(gsl.gsl_matrix), ctypes.POINTER(gsl.gsl_matrix), ctypes.POINTER(gsl.gsl_matrix), ctypes.POINTER(gsl.gsl_vector)]
    qr_ud_decomp.restype = None
    qr_ud_decomp(U, D, Y, T)

    return array(Y).astype(float), array(T).astype(float)

