import ctypes
from typing import List

class GSLMatrix:
    def __init__(self, matrix: List[List[float]]):
        self.matrix = self._convert_to_gsl(matrix)

    def _convert_to_gsl(self, matrix: List[List[float]]) -> ctypes.POINTER(ctypes.c_double):
        return ctypes.cast(self._create_gsl_array(matrix), ctypes.POINTER(ctypes.c_double))

    def _create_gsl_array(self, matrix: List[List[float]]) -> ctypes.ndarray:
        rows = len(matrix)
        cols = len(matrix[0])
        data = (ctypes.c_double * (rows * cols))()
        for i in range(rows):
            for j in range(cols):
                data[i * cols + j] = matrix[i][j]
        return data

    def __str__(self) -> str:
        return str(self.matrix)

def matrix_to_gsl(matrix: List[List[float]]) -> GSLMatrix:
    return GSLMatrix(matrix)

def gsl_matrix_to_numpy(gsl_matrix: ctypes.POINTER(ctypes.c_double)) -> List[List[float]]:
    rows = int(gsl_matrix.contents.size / (gsl_matrix.contents.stride * 1))
    cols = int(gsl_matrix.contents.stride)
    data = [(gsl_matrix.contents[i * cols + j]) for i in range(rows) for j in range(cols)]
    return [data[i * cols : (i + 1) * cols] for i in range((len(data) // cols))]

def compute_matrix_exponential(matrix: List[List[float]], mode: int) -> List[List[float]]:
    gsl = ctypes.CDLL('/usr/local/gsl/lib/libgsl.so')
    cblas = ctypes.CDLL('/usr/local/gsl/lib/libgslcblas.so', mode=ctypes.RTLD_GLOBAL)
    matrix_gsl = matrix_to_gsl(matrix)
    exp_matrix_gsl = gsl.gsl_linalg_exponential_ss(matrix_gsl.matrix, mode)
    return gsl_matrix_to_numpy(exp_matrix_gsl)


def test():
    matrix = [[1, 2], [3, 4]]
    mode = 1
    expected_result = [[5.0, 6.0], [9.0, 12.0]]
    actual_result = compute_matrix_exponential(matrix, mode)
    assert actual_result == expected_result

