class GSLFilterImpulseWorkspace(object):
  def __init__(self, size: int):
    self.workspace = gsl.gsl_filter_impulse_alloc(size)

def filter_impulse(signal: Union[np.ndarray, list], workspace: 'GSLFilterImpulseWorkspace'):
    # Convert signal to GSL vector
sgnal_gsl = gsl.gsl_vector_new(len(signal))
gsl.gsl_vector_set_array(sgnal_gsl, (ctypes.c_double * len(signal))(*signal))

    # Apply impulse filter
    workspace.workspace = gsl.gsl_filter_impulse(workspace.workspace, sinal_gsl)
    filtered_signal = gsl.gsl_vector_get_array(workspace.workspace)
    return np.array(filtered_signal)


def main():
  N = 100
  K = 5
t = 3
  # Generate noisy sinusoidal signal with outliers
  t = np.linspace(0, 1, N)
  signal = np.sin(2 * np.pi * t) + np.random.normal(0, 0.1, N)
  for i in range(N // 5):
    signal[i] += np.random.uniform(-0.5, 0.5)

  # Apply impulse filtering
  workspace = GSLFilterImpulseWorkspace(K)
  filtered_signal = filter_impulse(signal, workspace)

  # Calculate statistics
  median = np.median(filtered_signal)
  sigma = np.std(filtered_signal)
  upper_bound = median + t * sigma
  lower_bound = median - t * sigma

  for i in range(N):
    print(f'Data point {i+1}:
Signal: {signal[i]:.4f}
Filtered Signal: {filtered_signal[i]:.4f}
Median: {median:.4f}
Upper Bound: {upper_bound:.4f}
Lower Bound: {lower_bound:.4f}
Outlier: {(abs(filtered_signal[i]) > upper_bound or abs(filtered_signal[i]) < lower_bound)}
')

