    rows, cols = matrix.shape
    A = gsl.gsl_matrix_alloc(rows, cols)
    for i in range(rows):
        for j in range(cols):
            A[i, j] = matrix[i][j]
    perm = gsl.gsl_permutation_alloc(rows)
    result = gsl.gsl_linalg_pcholesky_decomp(A, perm)
