import ctypes

def bspline_fit(x, y, weights=None):
  try:
    ctypes.CDLL('/usr/local/gsl/lib/libgslcblas.so', mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL('/usr/local/gsl/lib/libgsl.so')
    x_gsl = gsl.gsl_vector_alloc(len(x))
    y_gsl = gsl.gsl_vector_alloc(len(y))
    for i in range(len(x)):
      x_gsl[i] = x[i]
      y_gsl[i] = y[i]
    if weights is not None:
      weights_gsl = gsl.gsl_vector_alloc(len(weights))
      for i in range(len(weights)):
        weights_gsl[i] = weights[i]
      workspace = gsl.gsl_bspline_workspace_alloc(len(x) - 1, len(x), 3)
      coefficients, chi_squared = gsl.bspline_wlssolve(x_gsl, y_gsl, weights_gsl, workspace)
    else:
      workspace = gsl.gsl_bspline_workspace_alloc(len(x) - 1, len(x), 3)
      coefficients, chi_squared = gsl.bspline_wlssolve(x_gsl, y_gsl, None, workspace)
    gsl.gsl_vector_free(x_gsl)
    gsl.gsl_vector_free(y_gsl)
    if weights is not None:
      gsl.gsl_vector_free(weights_gsl)
    return coefficients.tolist(), chi_squared
  except IndexError as e:
    print('Error: Mismatched array lengths.')
    return [], float('nan')

