        self._ptr = gsl.gsl_vector_alloc(size)

    def __getitem__(self, idx):
        return self._ptr[idx]

    def __setitem__(self, idx, value):
        self._ptr[idx] = value

    @property
    def size(self):
        return gsl.gsl_vector_get_size(self._ptr)


def matrix_to_gsl(matrix):
    rows, cols = len(matrix), len(matrix[0])
    gsl_mat = gsl_matrix(rows, cols)

    for i in range(rows):
        for j in range(cols):
            gsl_mat[i, j] = matrix[i][j]

    return gsl_mat

def vector_to_gsl(vector):
    gsl_vec = gsl_vector(len(vector))

    for i in range(len(vector)):
        gsl_vec[i] = vector[i]

    return gsl_vec

def gsl_matrix_to_list(matrix):
    rows, cols = matrix.rows, matrix.cols
    result = [[0 for _ in range(cols)] for _ in range(rows)]

    for i in range(rows):
        for j in range(cols):
            result[i][j] = matrix[i, j]

    return result

def gsl_vector_to_list(vector):
    return [vector[i] for i in range(vector.size)]


def ql_decomposition_and_unpack(A, tau):
    gsl_A = matrix_to_gsl(A)
    gsl_tau = vector_to_gsl(tau)

    n = gsl_A.cols 
    m = gsl_A.rows

    q = gsl_matrix(m, m)
    l = gsl_matrix(m, n)

    gsl.gsl_linalg_QL_decomp(byref(gsl_A), byref(q), byref(l)) 

    return gsl_matrix_to_list(q), gsl_matrix_to_list(l)

