import ctypes

ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

def cholesky_decomposition(matrix):
    GSLMatrix = gsl.gsl_matrix_view_array(ctypes.c_int(len(matrix)), ctypes.c_int(len(matrix)), (ctypes.POINTER(ctypes.c_double) * len(matrix))(*[(i * len(matrix) + j) for i in range(len(matrix)) for j in range(len(matrix))]))
    GSLMatrix.data = (ctypes.c_double * (len(matrix)**2))(*[(i * len(matrix) + j) for i in range(len(matrix)) for j in range(len(matrix))])

    for i in range(len(matrix)):
        for j in range(len(matrix)):
            GSLMatrix.data[i * len(matrix) + j] = matrix[i][j]

    if gsl.gsl_linalg_is_positive_definite(GSLMatrix):
        result = gsl.gsl_linalg_cholesky_decomp(GSLMatrix)
        return [[result[i * len(matrix) + j] for j in range(len(matrix))] for i in range(len(matrix))]
    else:
        raise ValueError("Matrix is not positive definite")

